// Context features of a hit, and the small model that turns them (with the pattern's own record) into a trust multiplier.
// The pattern table (reliability.ts) says how often a pattern is right on average; this says whether it is probably right
// *here*: in a sexual stretch, about the people it names, without a fight, a baby or a "what if" around it.
// MODEL is generated by tests/learn.test.ts from tests/labels/*.json. Do not edit it by hand.
import { NEG } from "./markers";
import { precisionOf, reliabilityOf } from "./reliability";

export const FEATURES = [
  "sexLocal", // sexual vocabulary in this paragraph and its neighbours (log count)
  "sexWide", // … within four paragraphs either way (log count)
  "named", // the people were found by name
  "pronoun", // … through pronouns (neither: inferred)
  "elided", // the subject was left out of the sentence and carried over
  "neg", // a negation in the sentence
  "hypo", // would / could / if / wish / imagine in the sentence
  "fight", // fighting words in the sentence or the paragraph
  "child", // a baby or child in the neighbouring paragraphs
  "len", // sentence length (log words)
  "pairBoth", // both people are one declared pairing
  "actorNamed", // the one credited as doing it is named in the sentence
  "noNames", // nobody at all is named in the sentence
  "penis", // a cock word in the sentence
  "question", // the sentence is a question
] as const;

export interface FeatureInput {
  sent: string;
  paras: string[];
  pi: number;
  basis: "named" | "pronoun" | "inferred";
  elided: boolean;
  pairBoth: boolean;
  actorNamed: boolean;
  anyNamed: boolean;
}

const SEXW = /\b(?:cock|dick|prick|hole|ass|arse|thrust\w*|moan\w*|gasp\w*|groan\w*|cum|come|coming|lube\w*|naked|bare|bed|mouth|tongue|fingers?|knot|inside|hips|nipples?|kiss\w*|hard|aroused|orgasm\w*|pleasure|whimper\w*|panting|sweat\w*|skin)\b/gi;
const HYPO = /\b(?:would|could|might|wish\w*|want\w*|imagin\w*|dream\w*|fantas\w*|if|wonder\w*|maybe|someday|hoped?)\b/i;
const FIGHT = /\b(?:punch\w*|fight\w*|blood\w*|knife|gun|shot|kill\w*|battle|swung|swing|blow|bruise\w*|bleed\w*|sword|attack\w*|wrestl\w*|tackl\w*|slap\w*)\b/i;
const CHILD = /\b(?:(?:the|a|their|his|her|my|our)\s+(?:little\s+)?baby|babies|toddler|infant|child|children|kids?|crib|diaper|cradle|newborn|nursery)\b/i;
const count = (ps: string[]) => ps.reduce((n, p) => n + (p.match(SEXW)?.length ?? 0), 0);

export function featuresOf(i: FeatureInput): number[] {
  const near = i.paras.slice(Math.max(0, i.pi - 1), i.pi + 2);
  const wide = i.paras.slice(Math.max(0, i.pi - 4), i.pi + 5);
  const here = i.paras[i.pi] ?? "";
  return [
    Math.log1p(count(near)),
    Math.log1p(count(wide)),
    i.basis === "named" ? 1 : 0,
    i.basis === "pronoun" ? 1 : 0,
    i.elided ? 1 : 0,
    NEG.test(i.sent) ? 1 : 0,
    HYPO.test(i.sent) ? 1 : 0,
    FIGHT.test(i.sent) || FIGHT.test(here) ? 1 : 0,
    CHILD.test(near.join(" ")) ? 1 : 0,
    Math.log(1 + i.sent.split(/\s+/).length),
    i.pairBoth ? 1 : 0,
    i.actorNamed ? 1 : 0,
    i.anyNamed ? 0 : 1,
    /\b(?:cock|dick|prick|length|shaft)\b/i.test(i.sent) ? 1 : 0,
    /\?\s*$/.test(i.sent.trim()) ? 1 : 0,
  ];
}

const logit = (p: number) => Math.log(p / (1 - p));
const sigmoid = (x: number) => 1 / (1 + Math.exp(-x));
export const FLOOR = 0.4;

/** Probability the hit is read right, from the pattern's record (its precision) and the features. */
export function probability(precision: number, f: number[], model = MODEL): number {
  let z = model.bias + model.prior * logit(Math.min(0.99, Math.max(0.01, precision)));
  for (let k = 0; k < f.length; k++) z += (model.weights[k] ?? 0) * f[k];
  return sigmoid(z);
}

/** What a hit's weight is multiplied by: the model's trust where it has been trained, else the plain pattern record. */
export function trustOf(id: string, f: number[]): number {
  if (!MODEL.enabled) return reliabilityOf(id);
  const p = probability(precisionOf(id), f);
  return Math.max(FLOOR, Math.min(1, p / 0.9));
}

export const MODEL: { enabled: boolean; bias: number; prior: number; weights: number[] } = {
  enabled: true,
  bias: 1.4267,
  prior: 0.7344,
  weights: [0.2296, 0.2654, 0.3421, 0.1040, -0.3806, -0.0706, 0.0492, -0.1509, -0.0283, -0.6975, 1.0012, 0.3209, -0.2921, -0.1249, 0.0065],
};
